command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "118b92c77c5ca8a78207b5236c42fa688796d108") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "3984884008f30f67434efaa5c963b68c565f79c2") { throw "work branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout work branch failed" }
$global:LASTEXITCODE=0
git merge --no-commit --no-ff origin/main
$mergeExit=$LASTEXITCODE
if ($mergeExit -ne 0) {
  $unmerged=@(git diff --name-only --diff-filter=U)
  if ($unmerged.Count -ne 2 -or $unmerged -notcontains "AGENTS.md" -or $unmerged -notcontains "tests/winui/test_external_context_contract.py") { git merge --abort 2>$null; throw ("unexpected merge conflicts: " + ($unmerged -join ", ")) }
  git checkout --theirs -- AGENTS.md tests/winui/test_external_context_contract.py
  if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "conflict resolution checkout failed" }
}
$utf8NoBom=New-Object System.Text.UTF8Encoding($false)
$contextPath="tests/winui/test_external_context_contract.py"
$context=Get-Content -Raw -Encoding UTF8 -LiteralPath $contextPath
$oldResident='"items[index].isFileSystem()",'
$newIndexed='"session.indexedItem(","indexed->isFileSystem()",'
if (-not $context.Contains($oldResident)) { git merge --abort 2>$null; throw "resident context assertion missing" }
$context=$context.Replace($oldResident,$newIndexed).TrimEnd([char]13,[char]10)+[Environment]::NewLine
[System.IO.File]::WriteAllText((Resolve-Path $contextPath),$context,$utf8NoBom)
$largePath=("tests\winui\test_large_owned_folder_" + "gui.py")
$large=Get-Content -Raw -Encoding UTF8 -LiteralPath $largePath
$large=$large.Replace('until(lambda:"bench-20499.txt" in fresh_first_row(),' + [Environment]::NewLine + '                  "indexed global name sort above 20k did not complete",16)', 'until(lambda:"bench-9999.txt" in fresh_first_row(),' + [Environment]::NewLine + '                  "indexed global name sort above 20k did not complete",16)')
$large=$large.Replace('until(lambda:"bench-20499.txt" in fresh_first_row(),' + [Environment]::NewLine + '                  "clearing indexed filter did not restore indexed name sort",12)', 'until(lambda:"bench-9999.txt" in fresh_first_row(),' + [Environment]::NewLine + '                  "clearing indexed filter did not restore indexed name sort",12)')
$large=$large.Replace('assert "bench-20499.txt" in fresh_first_row()','assert "bench-9999.txt" in fresh_first_row()')
if (($large -split "bench-9999.txt").Count -lt 4) { git merge --abort 2>$null; throw "indexed-name assertion replacements incomplete" }
$large=$large.TrimEnd([char]13,[char]10)+[Environment]::NewLine
[System.IO.File]::WriteAllText((Resolve-Path $largePath),$large,$utf8NoBom)
git add AGENTS.md $contextPath $largePath
if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "staging merge resolution failed" }
$remaining=@(git diff --name-only --diff-filter=U)
if($remaining.Count -ne 0){ git merge --abort 2>$null; throw ("unresolved conflicts remain: " + ($remaining -join ", ")) }
git diff --check --cached
if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "staged diff check failed" }
git commit -m "merge: integrate current main into large-folder name index"
if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "merge commit failed" }
$newHead=(git rev-parse HEAD).Trim()
Write-Host ("INTEGRATED_HEAD=" + $newHead)
git push origin HEAD:refs/heads/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "push integrated work branch failed" }
Write-Host "LARGE_FOLDER_NAME_INDEX_MAIN_RESOLUTION_PASS"
